(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.22)*12;
  const w2 = Math.cos(y*0.016-t*0.2)*14 + Math.sin(x*0.022+t*0.32)*9;
  const w3 = Math.sin((x+y)*0.01+t*0.15)*8;
  const sx = x + w1 + w3*0.5, sy = y + w2 + w3*0.5;
  const src = [
    [120+Math.sin(t*0.45)*110, 70+Math.cos(t*0.35)*50, 0.07, 2.2],
    [360+Math.cos(t*0.5)*90, 100+Math.sin(t*0.6)*60, 0.09, 1.8],
    [240+Math.sin(t*0.3+2)*150, 130+Math.cos(t*0.45+1)*80, 0.055, 2.5],
    [80+Math.cos(t*0.7+1)*70, 190+Math.sin(t*0.55+3)*50, 0.11, 1.6],
    [400+Math.sin(t*0.4+4)*80, 50+Math.cos(t*0.8+2)*60, 0.065, 2.8],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*70, 0.085, 2.0],
    [300+Math.sin(t*0.55+3)*100, 180+Math.cos(t*0.38+4)*55, 0.075, 2.3],
    [160+Math.cos(t*0.42+1)*90, 30+Math.sin(t*0.65+2)*40, 0.095, 1.9]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.55+1.5);
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2]=src[j];
      const mx=(sX+sX2)*0.5+Math.sin(t*0.4+i+j)*20;
      const my=(sY+sY2)*0.5+Math.cos(t*0.35+i+j)*15;
      const d2=Math.sqrt((sx-mx)**2+(sy-my)**2);
      cross+=Math.sin(d2*0.08-t*1.2)*0.15;
    }
  }
  const n=src.length, act=aS/n, inh=iS/n;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    +Math.sin((sx+sy)*0.11+t*2.3)*0.2+Math.sin((sx-sy)*0.09-t*1.8)*0.2
    +Math.sin(sx*0.06*sy*0.04+t*0.5)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.035+ang*4.5-t*1.0))*0.35;
  const radial=Math.sin(dist*0.06-t*2.5)*Math.cos(ang*2+t*0.4)*0.2;
  const warp=Math.sin(sx*0.02+sy*0.03+t)*Math.cos(sx*0.03-sy*0.02-t*0.7)*0.25;
  const feed=act*0.5-inh*0.35+bg*0.25+spiral*0.2+cross+radial+warp;
  const lap=feed-Math.sin(sx*0.12)*Math.sin(sy*0.12)*0.3;
  const reaction=Math.tanh(lap*2.5);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5+Math.sin((sx*2-sy)*0.07-t*0.8)*0.3)*1.8)*0.25;
  const micro=Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.08;
  const blend=reaction*0.65+cell*0.25+micro, v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[12,45,85],[18,95,120],[25,155,135],[180,185,60],
    [220,140,55],[195,75,55],[140,35,60],[65,18,55],[30,10,40],[5,12,45]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.82+Math.sin(reaction*Math.PI)*0.18;
  const edge=Math.abs(reaction)>0.65?1.18:Math.abs(reaction)>0.4?1.08:1.0;
  const glow=Math.max(0,reaction)*0.12;
  return [
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge+glow*80)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge+glow*100)|0)
  ];
}
